// marshalBoardsBoardStickyToBoardStickyResponseBody builds a value of type
// *BoardStickyResponseBody from a value of type *boards.BoardSticky.
func marshalBoardsBoardStickyToBoardStickyResponseBody(v *boards.BoardSticky) *BoardStickyResponseBody {
	res := &BoardStickyResponseBody{
		ID:        v.ID,
		Parent:    v.Parent,
		Kind:      v.Kind,
		State:     v.State,
		Error:     v.Error,
		Returns:   v.Returns,
		CreatedAt: v.CreatedAt,
		UpdatedAt: v.UpdatedAt,
	}
	if v.Anchor != nil {
		res.Anchor = marshalBoardsBoardAnchorToBoardAnchorResponseBody(v.Anchor)
	}
	if v.Messages != nil {
		res.Messages = make([]*BoardMessageResponseBody, len(v.Messages))
		for i, val := range v.Messages {
			if val == nil {
				res.Messages[i] = nil
				continue
			}
			res.Messages[i] = marshalBoardsBoardMessageToBoardMessageResponseBody(val)
		}
	} else {
		res.Messages = []*BoardMessageResponseBody{}
	}

	return res
}

